import os
import json
import base64
from flask import Flask, request, Response, send_from_directory, stream_with_context
from openai import OpenAI

app = Flask(__name__, static_folder=None)

_API_KEY = os.environ.get("HPC_AI_API_KEY", "")
_BASE_URL = os.environ.get("HPC_AI_BASE_URL", "")

client = OpenAI(
    api_key=_API_KEY if _API_KEY else "missing-api-key",
    base_url=_BASE_URL,
)

MODEL = os.environ.get("HPC_AI_MODEL", "glm-5.1")
MAX_TOKENS = int(os.environ.get("HPC_AI_MAX_TOKENS", "131072"))
if MAX_TOKENS < 1:
    MAX_TOKENS = 1
if MAX_TOKENS > 131072:
    MAX_TOKENS = 131072
TEMPERATURE = float(os.environ.get("HPC_AI_TEMPERATURE", "1.0"))
if TEMPERATURE < 0.01:
    TEMPERATURE = 0.01
if TEMPERATURE > 1.0:
    TEMPERATURE = 1.0
TOP_P = 0.95

_ALLOWED_ROLES = {"system", "user", "assistant", "tool", "developer"}


def _coerce_str(value, default=""):
    if value is None:
        return default
    if isinstance(value, str):
        return value
    try:
        return str(value)
    except Exception:
        return default


def _b64_marker(data_url):
    if not isinstance(data_url, str):
        return False
    if not data_url.startswith("data:"):
        return False
    head = data_url.split(",", 1)[0]
    return "base64" in head or "image/" in head


def _validate_remote_image_url(url):
    if not isinstance(url, str):
        return False
    return url.startswith("http://") or url.startswith("https://")


def _attachment_block(name, file_content, leading_newlines=True):
    safe_name = _coerce_str(name, "file").replace("---", "—")
    body = _coerce_str(file_content, "")
    prefix = "\n\n" if leading_newlines else ""
    return f"{prefix}--- {safe_name} ---\n{body}"


def build_openai_messages(messages):
    result = []
    has_system = False
    if isinstance(messages, list):
        for m in messages:
            if isinstance(m, dict) and m.get("role") == "system":
                has_system = True
                break
    if not has_system:
        result.append({"role": "system", "content": "You are a helpful assistant."})

    if not isinstance(messages, list):
        return result

    for m in messages:
        if not isinstance(m, dict):
            continue
        role = m.get("role", "user")
        if role not in _ALLOWED_ROLES:
            role = "user"
        content = m.get("content", "")
        if content is None:
            content = ""
        attachments = m.get("attachments") or {}
        if not isinstance(attachments, dict):
            attachments = {}
        imgs_raw = attachments.get("imgs")
        text_atts_raw = attachments.get("textAtts")
        imgs = imgs_raw if isinstance(imgs_raw, list) else []
        text_atts = text_atts_raw if isinstance(text_atts_raw, list) else []

        if role == "user":
            text_body = _coerce_str(content, "")
            if text_atts:
                if text_body:
                    for ta in text_atts:
                        if not isinstance(ta, dict):
                            continue
                        text_body += _attachment_block(ta.get("name"), ta.get("content"), leading_newlines=True)
                else:
                    first = True
                    for ta in text_atts:
                        if not isinstance(ta, dict):
                            continue
                        text_body += _attachment_block(ta.get("name"), ta.get("content"), leading_newlines=not first)
                        first = False

            parts = []
            if text_body:
                parts.append({"type": "text", "text": text_body})

            for img in imgs:
                if not isinstance(img, dict):
                    continue
                data_url = img.get("dataUrl", "")
                if isinstance(data_url, str) and (data_url.startswith("data:") or _validate_remote_image_url(data_url)):
                    parts.append({
                        "type": "image_url",
                        "image_url": {"url": data_url, "detail": "auto"},
                    })

            if not parts:
                continue

            has_image = any(p.get("type") == "image_url" for p in parts)
            has_text = any(p.get("type") == "text" for p in parts)
            if has_image and not has_text:
                parts.insert(0, {"type": "text", "text": "Please analyze the provided image(s)."})

            if len(parts) == 1 and parts[0]["type"] == "text":
                result.append({"role": "user", "content": parts[0]["text"]})
            else:
                result.append({"role": "user", "content": parts})

        elif role == "assistant":
            assistant_text = _coerce_str(content, "")
            if text_atts:
                first = not bool(assistant_text)
                for ta in text_atts:
                    if not isinstance(ta, dict):
                        continue
                    assistant_text += _attachment_block(ta.get("name"), ta.get("content"), leading_newlines=not first)
                    first = False
            if imgs:
                names = []
                for img in imgs:
                    if isinstance(img, dict):
                        names.append(_coerce_str(img.get("name"), "image"))
                if names:
                    assistant_text += "\n\n[Assistant previously referenced images: " + ", ".join(names) + "]"
            if not assistant_text:
                assistant_text = " "
            result.append({"role": "assistant", "content": assistant_text})

        elif role == "system":
            sys_text = _coerce_str(content, "")
            if sys_text:
                result.append({"role": "system", "content": sys_text})

        elif role == "tool":
            tool_call_id = m.get("tool_call_id")
            if not tool_call_id:
                continue
            result.append({
                "role": "tool",
                "tool_call_id": _coerce_str(tool_call_id, ""),
                "content": _coerce_str(content, ""),
            })

        elif role == "developer":
            dev_text = _coerce_str(content, "")
            if dev_text:
                result.append({"role": "developer", "content": dev_text})

    return result


def _sse_pack(event_type, payload_key, payload_value):
    data = json.dumps({"type": event_type, payload_key: payload_value}, ensure_ascii=False)
    data = data.replace("\r", " ").replace("\n", " ")
    return f"data: {data}\n\n"


def stream_chat(messages):
    try:
        openai_messages = build_openai_messages(messages)
    except Exception as e:
        yield _sse_pack("error", "message", f"message_build_failed: {e!r}")
        yield "data: [DONE]\n\n"
        return

    yield ": ping\n\n"

    stream_obj = None
    try:
        stream_obj = client.chat.completions.create(
            model=MODEL,
            messages=openai_messages,
            max_tokens=MAX_TOKENS,
            temperature=TEMPERATURE,
            top_p=TOP_P,
            stream=True,
            stream_options={"include_usage": True},
            extra_body={"thinking": {"type": "enabled"}},
        )

        finish_reason = None
        usage_payload = None

        for chunk in stream_obj:
            choices = getattr(chunk, "choices", None) or []
            usage = getattr(chunk, "usage", None)
            if usage is not None:
                try:
                    usage_payload = {
                        "prompt_tokens": getattr(usage, "prompt_tokens", None),
                        "completion_tokens": getattr(usage, "completion_tokens", None),
                        "total_tokens": getattr(usage, "total_tokens", None),
                    }
                except Exception:
                    usage_payload = None

            if not choices:
                continue

            choice0 = choices[0]
            delta = getattr(choice0, "delta", None)
            fr = getattr(choice0, "finish_reason", None)
            if fr:
                finish_reason = fr

            if delta is None:
                continue

            reasoning = getattr(delta, "reasoning_content", None)
            if reasoning is None:
                extras = getattr(delta, "model_extra", None) or {}
                if isinstance(extras, dict):
                    reasoning = extras.get("reasoning_content")
            content_piece = getattr(delta, "content", None)

            if reasoning:
                yield _sse_pack("thinking", "content", reasoning)
            if content_piece:
                yield _sse_pack("content", "content", content_piece)

        if finish_reason:
            yield _sse_pack("finish", "reason", finish_reason)
        if usage_payload:
            yield f"data: {json.dumps({'type': 'usage', 'usage': usage_payload}, ensure_ascii=False)}\n\n"

        yield "data: [DONE]\n\n"
    except GeneratorExit:
        try:
            if stream_obj is not None and hasattr(stream_obj, "close"):
                stream_obj.close()
        except Exception:
            pass
        raise
    except Exception as e:
        err_type = type(e).__name__
        status_code = getattr(e, "status_code", None)
        msg = f"{err_type}: {e}"
        if status_code is not None:
            msg = f"{err_type}[{status_code}]: {e}"
        yield _sse_pack("error", "message", msg)
        yield "data: [DONE]\n\n"
    finally:
        try:
            if stream_obj is not None and hasattr(stream_obj, "close"):
                stream_obj.close()
        except Exception:
            pass


@app.route("/", methods=["GET"])
def index():
    return send_from_directory(app.root_path, "index.html", mimetype="text/html")


@app.route("/favicon.ico", methods=["GET"])
def favicon():
    favicon_path = os.path.join(app.root_path, "favicon.ico")
    if os.path.isfile(favicon_path):
        return send_from_directory(app.root_path, "favicon.ico", mimetype="image/x-icon")
    return Response(b"", status=204, mimetype="image/x-icon")


@app.route("/healthz", methods=["GET"])
def healthz():
    payload = {
        "status": "ok",
        "model": MODEL,
        "max_tokens": MAX_TOKENS,
        "temperature": TEMPERATURE,
        "api_key_configured": bool(_API_KEY),
        "base_url": _BASE_URL,
        "base64_available": bool(base64),
    }
    return Response(
        json.dumps(payload, ensure_ascii=False),
        status=200,
        mimetype="application/json; charset=utf-8",
    )


@app.route("/chat", methods=["POST", "OPTIONS"])
def chat():
    if request.method == "OPTIONS":
        resp = Response(status=204)
        resp.headers["Access-Control-Allow-Origin"] = "*"
        resp.headers["Access-Control-Allow-Methods"] = "POST, OPTIONS"
        resp.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
        return resp

    data = request.get_json(force=True, silent=True)
    if not isinstance(data, dict):
        data = {}
    raw_messages = data.get("messages")
    if not isinstance(raw_messages, list):
        raw_messages = []

    response = Response(
        stream_with_context(stream_chat(raw_messages)),
        status=200,
        mimetype="text/event-stream; charset=utf-8",
        direct_passthrough=True,
        headers={
            "Cache-Control": "no-cache, no-transform",
            "Pragma": "no-cache",
            "X-Accel-Buffering": "no",
            "Access-Control-Allow-Origin": "*",
        },
    )
    return response


@app.errorhandler(404)
def _not_found(_e):
    return Response(
        json.dumps({"error": "not_found"}, ensure_ascii=False),
        status=404,
        mimetype="application/json; charset=utf-8",
    )


@app.errorhandler(500)
def _server_error(_e):
    return Response(
        json.dumps({"error": "internal_server_error"}, ensure_ascii=False),
        status=500,
        mimetype="application/json; charset=utf-8",
    )


if __name__ == "__main__":
    _host = os.environ.get("HOST", "0.0.0.0")
    _port = int(os.environ.get("PORT", "5000"))
    app.run(host=_host, port=_port, debug=False, threaded=True, use_reloader=False)



