    if not api_key:
        raise RuntimeError(f"{API_KEY_ENV} is not configured")
    if api_key == _client_api_key:
        return client
    return OpenAI(
        api_key=api_key,
        base_url=BASE_URL,
    )


def make_json_response(payload, status):
    return Response(
        json.dumps(payload, ensure_ascii=False),
        status=status,
        mimetype="application/json",
    )


def get_field(obj, name, default=None):
    if isinstance(obj, dict):
        return obj.get(name, default)
    return getattr(obj, name, default)


def sse_message(payload):
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"


def normalize_string(value, field_name, allow_none=True):
    if value is None and allow_none:
        return ""
    if isinstance(value, str):
        return value
    raise ValueError(f"{field_name} must be a string")


def normalize_dict(value, field_name, allow_none=True):
    if value is None and allow_none:
        return {}
    if isinstance(value, dict):
        return value
    raise ValueError(f"{field_name} must be an object")


def normalize_list(value, field_name, allow_none=True):
    if value is None and allow_none:
        return []
    if isinstance(value, list):
        return value
    raise ValueError(f"{field_name} must be an array")


def normalize_image_url(value, field_name):
    if not isinstance(value, str):
        raise ValueError(f"{field_name} must be a string")

    value = value.strip()
    if not value:
        return ""

    lower_value = value.lower()
    if lower_value.startswith("http://") or lower_value.startswith("https://"):
        return value

    if not lower_value.startswith("data:"):
        raise ValueError(f"{field_name} must be a data URL or an HTTP URL")

    if "," not in value:
        raise ValueError(f"{field_name} is not a valid data URL")

    header, payload = value.split(",", 1)
    header_lower = header.lower()

    if not header_lower.startswith("data:image/"):
        raise ValueError(f"{field_name} must contain image data")

    if ";base64" not in header_lower:
        raise ValueError(f"{field_name} must be base64 encoded")

    payload = payload.strip()
    if not payload:
        raise ValueError(f"{field_name} contains empty image data")

    try:
        decoded = base64.b64decode(payload, validate=True)
    except Exception:
        raise ValueError(f"{field_name} contains invalid base64 data")

    normalized_payload = base64.b64encode(decoded).decode("utf-8")
    return f"{header},{normalized_payload}"


def normalize_role(value, index):
    role = normalize_string(value, f"messages[{index}].role")
    if not role:
        role = "user"
    role = role.lower()
    if role == "developer":
        return "system"
    if role not in {"system", "user", "assistant"}:
        raise ValueError(f"messages[{index}].role is not supported")
    return role


def build_user_content(message, index):
    content = normalize_string(message.get("content", ""), f"messages[{index}].content")
    attachments = normalize_dict(message.get("attachments", {}), f"messages[{index}].attachments")
    imgs = normalize_list(attachments.get("imgs", []), f"messages[{index}].attachments.imgs")
    text_atts = normalize_list(attachments.get("textAtts", []), f"messages[{index}].attachments.textAtts")

    text_body = content

    for ta_index, ta in enumerate(text_atts):
        ta = normalize_dict(ta, f"messages[{index}].attachments.textAtts[{ta_index}]", allow_none=False)
        name = normalize_string(ta.get("name", "file"), f"messages[{index}].attachments.textAtts[{ta_index}].name")
        file_content = normalize_string(ta.get("content", ""), f"messages[{index}].attachments.textAtts[{ta_index}].content")
        if text_body:
            text_body += f"\n\n--- {name} ---\n{file_content}"
        else:
            text_body += f"--- {name} ---\n{file_content}"

    image_parts = []
    for img_index, img in enumerate(imgs):
        img = normalize_dict(img, f"messages[{index}].attachments.imgs[{img_index}]", allow_none=False)
        if "dataUrl" in img:
            image_value = img.get("dataUrl")
        else:
            image_value = img.get("url", "")
        normalized_url = normalize_image_url(image_value, f"messages[{index}].attachments.imgs[{img_index}].dataUrl")
        if normalized_url:
            image_parts.append({"type": "image_url", "image_url": {"url": normalized_url}})

    if not text_body and not image_parts:
        return None

    if image_parts:
        parts = []
        if text_body:
            parts.append({"type": "text", "text": text_body})
        parts.extend(image_parts)
        return parts

    return text_body


def build_openai_messages(messages):
    messages = normalize_list(messages, "messages", allow_none=False)

    result = []
    has_system_message = False
    has_user_message = False

    for index, message in enumerate(messages):
        message = normalize_dict(message, f"messages[{index}]", allow_none=False)
        role = normalize_role(message.get("role", "user"), index)

        if role == "system":
            content = normalize_string(message.get("content", ""), f"messages[{index}].content")
            if content:
                result.append({"role": "system", "content": content})
                has_system_message = True
            continue

        if role == "assistant":
            content = normalize_string(message.get("content", ""), f"messages[{index}].content")
            result.append({"role": "assistant", "content": content})
            continue

        content = build_user_content(message, index)
        if content is None:
            continue
        result.append({"role": "user", "content": content})
        has_user_message = True

    if not has_user_message:
        raise ValueError("messages must contain at least one non-empty user message")

    if not has_system_message:
        result.insert(0, {"role": "system", "content": "You are a helpful assistant."})

    return result


def stream_chat(openai_messages):
    try:
        active_client = get_openai_client()
        stream = active_client.chat.completions.create(
            model=MODEL,
            messages=openai_messages,
            max_tokens=MAX_TOKENS,
            temperature=TEMPERATURE,
            stream=True,
            extra_body={"thinking": {"type": "enabled", "budget_tokens": THINKING_BUDGET_TOKENS}},
        )

        for chunk in stream:
            choices = get_field(chunk, "choices", None)
            if not choices:
                continue

            choice = choices[0]
