import os
import json
import base64
from flask import Flask, request, Response, send_file
from openai import OpenAI

app = Flask(__name__)

def get_text_setting(name, default):
    value = os.environ.get(name)
    if value is None:
        return default
    value = value.strip()
    if value == "":
        return default
    return value

def get_int_setting(name, default, minimum=None, maximum=None):
    value = os.environ.get(name)
    if value is None or value.strip() == "":
        result = default
    else:
        try:
            result = int(value)
        except ValueError:
            result = default
    if minimum is not None and result < minimum:
        result = minimum
    if maximum is not None and result > maximum:
        result = maximum
    return result

def get_float_setting(name, default, minimum=None, maximum=None):
    value = os.environ.get(name)
    if value is None or value.strip() == "":
        result = default
    else:
        try:
            result = float(value)
        except ValueError:
            result = default
    if minimum is not None and result < minimum:
        result = minimum
    if maximum is not None and result > maximum:
        result = maximum
    return result

BASE_URL = get_text_setting("HPC_AI_BASE_URL", "")
MODEL = get_text_setting("HPC_AI_MODEL", "zai-org/glm-5.1")
MAX_TOKENS = get_int_setting("HPC_AI_MAX_TOKENS", 202000, 1, None)
TEMPERATURE = get_float_setting("HPC_AI_TEMPERATURE", 0.0, 0.0, 2.0)
THINKING_BUDGET_TOKENS = get_int_setting("HPC_AI_THINKING_BUDGET_TOKENS", 32000, 0, None)
TIMEOUT = get_float_setting("HPC_AI_TIMEOUT", 600.0, 1.0, None)
SYSTEM_MESSAGE = get_text_setting("HPC_AI_SYSTEM_MESSAGE", "You are a helpful assistant.")

client = None

def to_text(value):
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    try:
        return json.dumps(value, ensure_ascii=False)
    except (TypeError, ValueError):
        return str(value)

def require_list(value, label):
    if value is None:
        return []
    if not isinstance(value, list):
        raise ValueError(f"{label} must be a list.")
    return value

def normalize_role(value, index):
    role = to_text(value).strip().lower()
    if role == "":
        return "user"
    if role == "developer":
        return "system"
    if role in {"system", "user", "assistant"}:
        return role
    raise ValueError(f"messages[{index}].role is unsupported.")

def normalize_attachment_name(value):
    text = to_text(value).strip()
    if text == "":
        return "file"
    return " ".join(text.split())

def build_text_attachment_body(text_attachments, label):
    blocks = []
    for index, attachment in enumerate(text_attachments):
        if not isinstance(attachment, dict):
            raise ValueError(f"{label}[{index}] must be an object.")
        name = normalize_attachment_name(attachment.get("name", "file"))
        content = to_text(attachment.get("content", ""))
        blocks.append(f"--- {name} ---\n{content}")
    return "\n\n".join(blocks)

def is_supported_data_image_url(data_url):
    if not isinstance(data_url, str):
        return False
    header, separator, encoded = data_url.partition(",")
    if not header.startswith("data:") or separator != "," or encoded == "":
        return False
    lowered_header = header.lower()
    media_type = lowered_header[5:].split(";", 1)[0]
    if not media_type.startswith("image/"):
        return False
    if ";base64" not in lowered_header:
        return False
    try:
        base64.b64decode(encoded, validate=True)
    except Exception:
        return False
    return True

def is_supported_image_url(url):
    if not isinstance(url, str):
        return False
    url = url.strip()
    if url == "":
        return False
    if url.startswith("data:"):
        return is_supported_data_image_url(url)
    lowered_url = url.lower()
    return lowered_url.startswith("https://") or lowered_url.startswith("http://")

def normalize_image_url(value, label):
    url = to_text(value).strip()
    if url == "":
        raise ValueError(f"{label} is empty.")
    if not is_supported_image_url(url):
        raise ValueError(f"{label} is not a supported image URL.")
    return url

def normalize_content_parts(content, label):
    parts = []
    for index, part in enumerate(content):
        if not isinstance(part, dict):
            raise ValueError(f"{label}.content[{index}] must be an object.")
        part_type = to_text(part.get("type", "")).strip()
        if part_type == "text":
            text = to_text(part.get("text", ""))
            if text != "":
                parts.append({"type": "text", "text": text})
        elif part_type == "image_url":
            image_url = part.get("image_url", "")
            if isinstance(image_url, dict):
                url = normalize_image_url(image_url.get("url", ""), f"{label}.content[{index}].image_url.url")
            else:
                url = normalize_image_url(image_url, f"{label}.content[{index}].image_url")
            parts.append({"type": "image_url", "image_url": {"url": url}})
        else:
            raise ValueError(f"{label}.content[{index}].type is unsupported.")
    return parts

def append_user_attachments(parts, attachments, message_index):
    if attachments is None:
        attachments = {}
    if not isinstance(attachments, dict):
        raise ValueError(f"messages[{message_index}].attachments must be an object.")
    text_attachments = require_list(attachments.get("textAtts"), f"messages[{message_index}].attachments.textAtts")
    image_attachments = require_list(attachments.get("imgs"), f"messages[{message_index}].attachments.imgs")
    attachment_text = build_text_attachment_body(text_attachments, f"messages[{message_index}].attachments.textAtts")
    if attachment_text != "":
        parts.append({"type": "text", "text": attachment_text})
    for image_index, image in enumerate(image_attachments):
        if not isinstance(image, dict):
            raise ValueError(f"messages[{message_index}].attachments.imgs[{image_index}] must be an object.")
        image_url_value = image.get("dataUrl", image.get("url", ""))
        image_url = normalize_image_url(image_url_value, f"messages[{message_index}].attachments.imgs[{image_index}]")
        parts.append({"type": "image_url", "image_url": {"url": image_url}})

def build_openai_messages(messages):
    if not isinstance(messages, list):
        raise ValueError("messages must be a list.")
    result = []
    if SYSTEM_MESSAGE != "":
        result.append({"role": "system", "content": SYSTEM_MESSAGE})
    for index, message in enumerate(messages):
        if not isinstance(message, dict):
            raise ValueError(f"messages[{index}] must be an object.")
        role = normalize_role(message.get("role", "user"), index)
        content = message.get("content", "")
        if role == "user":
            parts = []
            if isinstance(content, list):
                parts.extend(normalize_content_parts(content, f"messages[{index}]"))
            else:
                text = to_text(content)
                if text != "":
                    parts.append({"type": "text", "text": text})
            append_user_attachments(parts, message.get("attachments"), index)

            has_image = any(p.get("type") == "image_url" for p in parts)
            has_text = any(p.get("type") == "text" for p in parts)
            if has_image and not has_text:
                parts.insert(0, {"type": "text", "text": "Please analyze the provided image(s)."})

            if len(parts) == 0:
                result.append({"role": "user", "content": ""})
            elif len(parts) == 1 and parts[0]["type"] == "text":
                result.append({"role": "user", "content": parts[0]["text"]})
            else:
                result.append({"role": "user", "content": parts})
        else:
            text = to_text(content)
            if text != "":
                result.append({"role": role, "content": text})
    return result

def get_openai_client():
    global client
    if client is not None:
        return client
    api_key = os.environ.get("HPC_AI_API_KEY", "").strip()
    if api_key == "":
        raise RuntimeError("HPC_AI_API_KEY is not configured.")
    client = OpenAI(api_key=api_key, base_url=BASE_URL, timeout=TIMEOUT)
    return client

def build_extra_body():
    if THINKING_BUDGET_TOKENS <= 0:
        return None
    return {"thinking": {"type": "enabled", "budget_tokens": THINKING_BUDGET_TOKENS}}

def sse_payload(payload):
    return f"data: {json.dumps(payload, ensure_ascii=False, separators=(',', ':'))}\n\n"

def sse_done():
    return "data: [DONE]\n\n"

def stream_chat(messages):
    try:
        openai_messages = build_openai_messages(messages)
        request_options = {
            "model": MODEL,
            "messages": openai_messages,
            "max_tokens": MAX_TOKENS,
            "temperature": TEMPERATURE,
            "stream": True,
        }
        extra_body = build_extra_body()
        if extra_body is not None:
            request_options["extra_body"] = extra_body
        stream = get_openai_client().chat.completions.create(**request_options)
        for chunk in stream:
            choices = getattr(chunk, "choices", None)
            if not choices:
                continue
            delta = getattr(choices[0], "delta", None)
            if delta is None:
                continue
            reasoning = getattr(delta, "reasoning_content", None)
            content = getattr(delta, "content", None)
            if reasoning is not None and reasoning != "":
                yield sse_payload({"type": "thinking", "content": to_text(reasoning)})
            if content is not None and content != "":
                yield sse_payload({"type": "content", "content": to_text(content)})
        yield sse_done()
    except (ValueError, RuntimeError) as error:
        yield sse_payload({"type": "error", "message": str(error)})
        yield sse_done()
    except Exception:
        yield sse_payload({"type": "error", "message": "The chat completion request failed."})
        yield sse_done()

def json_response(payload, status):
    return Response(json.dumps(payload, ensure_ascii=False), status=status, mimetype="application/json")

@app.route("/", methods=["GET"])
def index():
    index_path = os.path.join(app.root_path, "index.html")
    if not os.path.isfile(index_path):
        return Response("index.html not found\n", status=404, mimetype="text/plain")
    return send_file(index_path)

@app.route("/favicon.ico", methods=["GET"])
def favicon():
    favicon_path = os.path.join(app.root_path, "favicon.ico")
    if os.path.isfile(favicon_path):
